/* FileRoom service worker - generated by main.py from pwa/sw.template.js on every server start.
 * Staged, verified installs (like the Vokabeltrainer PWA): a new release is downloaded completely,
 * every file is checked against its SHA-256 checksum, and the running version stays active until the
 * user explicitly restarts the app. Room data (API, WebSocket, uploads) always goes to the network.
 */
const BUILD = __BUILD__;
const APP_VERSION = __VERSION__;
const ASSETS = __ASSETS__;
const CACHE_PREFIX = 'fileroom-pwa-';
const CACHE = CACHE_PREFIX + BUILD;
const SHA_HEADER = 'x-fileroom-sha256';
const ROOM_SHELL = '/shell/room.html';
const SHARE_SHELL = '/shell/share.html';
const NETWORK_ONLY = ['/api/', '/ws/', '/share', '/sw.js', '/version.json', '/health'];

async function broadcast(data) {
  const clients = await self.clients.matchAll({ includeUncontrolled: true, type: 'window' });
  await Promise.all(clients.map((client) => client.postMessage(data)));
}
async function sha256(buffer) {
  const d = new Uint8Array(await crypto.subtle.digest('SHA-256', buffer));
  return Array.from(d, (v) => v.toString(16).padStart(2, '0')).join('');
}
function withHash(buffer, contentType, hash) {
  const headers = new Headers({ [SHA_HEADER]: hash });
  if (contentType) headers.set('content-type', contentType);
  return new Response(buffer, { status: 200, headers });
}
async function reuse(url, hash, oldCaches) {
  for (const cache of oldCaches) {
    const match = await cache.match(url);
    if (!match || match.headers.get(SHA_HEADER) !== hash) continue;
    const body = await match.arrayBuffer();
    if (await sha256(body) === hash) return withHash(body, match.headers.get('content-type'), hash);
  }
  return null;
}
async function download(url, hash) {
  // A stale proxy/CDN response must never produce a mixed-version install.
  for (let attempt = 0; attempt < 2; attempt++) {
    const target = attempt ? `${url}${url.includes('?') ? '&' : '?'}build=${BUILD}` : url;
    const response = await fetch(target, { cache: 'reload', credentials: 'same-origin' });
    if (!response.ok || response.type === 'opaque') throw new Error(`${url}: HTTP ${response.status}`);
    const body = await response.arrayBuffer();
    if (await sha256(body) === hash) return withHash(body, response.headers.get('content-type'), hash);
  }
  throw new Error(`${url}: file does not match the release`);
}
async function install() {
  const cache = await caches.open(CACHE);
  const previousNames = (await caches.keys()).filter((key) => key.startsWith(CACHE_PREFIX) && key !== CACHE);
  const previous = await Promise.all(previousNames.map((key) => caches.open(key)));
  let done = 0;
  const queue = ASSETS.slice();
  await Promise.all(Array.from({ length: Math.min(queue.length, 4) }, async () => {
    while (queue.length) {
      const [path, hash] = queue.shift();
      const url = new URL(path, self.location.origin).href;
      const cached = await cache.match(url);
      const valid = cached && cached.headers.get(SHA_HEADER) === hash && await sha256(await cached.clone().arrayBuffer()) === hash;
      const response = valid ? cached : (await reuse(url, hash, previous)) || (await download(url, hash));
      if (!valid) await cache.put(url, response);
      done++;
      await broadcast({ type: 'INSTALL_PROGRESS', build: BUILD, version: APP_VERSION, done, total: ASSETS.length });
    }
  }));
}

self.addEventListener('install', (event) => {
  event.waitUntil(install().catch(async (error) => {
    await caches.delete(CACHE);
    await broadcast({ type: 'INSTALL_FAILED', build: BUILD, error: String(error?.message || error) });
    throw error; // a failed update must not replace the working version
  }));
  // No skipWaiting here: the user restarts once all files are downloaded and verified.
});

self.addEventListener('message', (event) => {
  if (event.data?.type === 'SKIP_WAITING') self.skipWaiting();
  if (event.data?.type === 'GET_VERSION') event.source?.postMessage({ type: 'VERSION', build: BUILD, version: APP_VERSION });
});

self.addEventListener('activate', (event) => event.waitUntil((async () => {
  for (const name of await caches.keys()) {
    // Remove older releases and the caches of the legacy /static/js/sw.js worker.
    if ((name.startsWith(CACHE_PREFIX) && name !== CACHE) || /^fileroom-(v\d+|runtime-v\d+)$/.test(name)) {
      await caches.delete(name);
    }
  }
  await self.clients.claim();
})()));

async function fromCache(path) {
  const cache = await caches.open(CACHE);
  return cache.match(new URL(path, self.location.origin).href);
}

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET') return; // uploads, share target POST, deletes: network only
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return; // map tiles etc.
  if (NETWORK_ONLY.some((prefix) => url.pathname === prefix || url.pathname.startsWith(prefix))) return;

  if (request.mode === 'navigate') {
    event.respondWith((async () => {
      if (url.pathname.startsWith('/room/')) {
        // Room pages are a static app shell; the room code is read from the URL.
        const shell = await fromCache(ROOM_SHELL);
        if (shell) return shell;
      } else if (url.pathname === '/' && url.searchParams.has('share')) {
        const shell = await fromCache(SHARE_SHELL);
        if (shell) return shell;
      }
      try {
        return await fetch(request);
      } catch (err) {
        const shell = await fromCache(url.searchParams.has('share') ? SHARE_SHELL : ROOM_SHELL);
        if (shell) return shell; // offline: the app shell shows the offline state
        throw err;
      }
    })());
    return;
  }

  event.respondWith((async () => {
    // Static assets are versioned with ?v=<build>; the cache is keyed by path only.
    const cached = await fromCache(url.pathname);
    if (cached) return cached;
    return fetch(request);
  })());
});
